/* ===== Topical questions (Cambridge IGCSE 0620 style): Topic 1 particulate nature of matter, Topic 2 bonding (+ one organic question).
   Question wording is transcribed from the teacher's topical question sheets. The answers were written for this hub and are NOT the official mark scheme.
   Diagrams were redrawn as simplified SVG. Questions that ask for a graph to be sketched were left out. ===== */
const X1_FG=(vb,inner,cap,label,maxw)=>`<figure class="fig"${maxw?` style="max-width:${maxw}px"`:""}><svg viewBox="${vb}" role="img" aria-label="${label}">${inner}</svg>${cap?`<figcaption>${cap}</figcaption>`:""}</figure>`;
const X1_T=(x,y,s,o)=>{o=o||{};return `<text x="${x}" y="${y}" font-size="${o.s||12}" text-anchor="${o.a||"middle"}"${o.b?' font-weight="700"':""} fill="currentColor">${s}</text>`};
const X1_C=(x,y,r,t,fs)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="none" stroke="currentColor" stroke-opacity=".75" stroke-width="1.3"/>`+(t?X1_T(x,y+(fs||11)*.36,t,{s:fs||11}):"");
const X1_L=(x1,y1,x2,y2,w,dash)=>`<path d="M${x1} ${y1}L${x2} ${y2}" stroke="currentColor" stroke-width="${w||1.4}" fill="none"${dash?' stroke-dasharray="3 3"':""}/>`;
const X1_SRC=t=>"Cambridge IGCSE 0620 topical question, "+t+", Question ";

/* extra covalent molecules for the dot-and-cross renderer (cov.js) */
COVM.ICl=["Iodine monochloride, ICl","One shared pair. Iodine and chlorine each keep three non-bonding pairs.",[["I",-1,0,0,"d",3],["Cl",0,0,1,"x",3]]];
COVM.NF3=["Nitrogen trifluoride, NF~3~","Three shared pairs. Nitrogen keeps one non-bonding pair and each fluorine keeps three.",[["N",-1,0,0,"d",1],["F",0,190,1,"x",3],["F",0,350,1,"x",3],["F",0,270,1,"x",3]]];
COVM.COF2=["Carbonyl fluoride, COF~2~","One C=O double bond and two C–F single bonds. Every atom has eight outer electrons.",[["C",-1,0,0,"d",0],["O",0,270,2,"x",2],["F",0,150,1,"x",3],["F",0,30,1,"x",3]]];
COVM.PCl3=["Phosphorus trichloride, PCl~3~","Three shared pairs. Phosphorus keeps one non-bonding pair and each chlorine keeps three.",[["P",-1,0,0,"d",1],["Cl",0,150,1,"x",3],["Cl",0,30,1,"x",3],["Cl",0,270,1,"x",3]]];
COVM.PH3=["Phosphine, PH~3~","Three shared pairs. Phosphorus keeps one non-bonding pair.",[["P",-1,0,0,"d",1],["H",0,90,1,"x",0],["H",0,200,1,"x",0],["H",0,340,1,"x",0]]];
COVM.C2H2=["Ethyne, C~2~H~2~","The two carbons share three pairs (a C≡C triple bond). Each carbon also shares one pair with hydrogen.",[["C",-1,0,0,"d",0],["C",0,0,3,"x",0],["H",0,180,1,"x",0],["H",1,0,1,"d",0]]];
COVM.SCl2=["Sulfur dichloride, SCl~2~","Two shared pairs. Sulfur keeps two non-bonding pairs and each chlorine keeps three.",[["S",-1,0,0,"d",2],["Cl",0,210,1,"x",3],["Cl",0,330,1,"x",3]]];
COVM.C2H5OH=["Ethanol, C~2~H~5~OH","Every C–H, C–C, C–O and O–H bond is one shared pair. Oxygen keeps two non-bonding pairs.",[["C",-1,0,0,"d",0],["H",0,90,1,"x",0],["H",0,180,1,"x",0],["H",0,270,1,"x",0],["C",0,0,1,"x",0],["H",4,90,1,"d",0],["H",4,270,1,"d",0],["O",4,0,1,"d",2],["H",7,0,1,"x",0]]];
COVM.CH3CHO=["Ethanal, CH~3~CHO","One C=O double bond. Oxygen keeps two non-bonding pairs.",[["C",-1,0,0,"d",0],["H",0,90,1,"x",0],["H",0,180,1,"x",0],["H",0,270,1,"x",0],["C",0,0,1,"x",0],["O",4,0,2,"d",2],["H",4,270,1,"d",0]]];

/* ion diagrams: items [{s, rings:[[r, n electrons, markers]], ch}] ; markers is "d", "x" or a string with one letter per electron */
function X1_ION(items,cap,label){
  const W=150,mk=(k,x,y)=>k==="d"?`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="3" style="fill:var(--bad)"/>`:`<path d="M${(x-3).toFixed(1)} ${(y-3).toFixed(1)}l6 6m0 -6l-6 6" style="stroke:var(--accent)" stroke-width="2" stroke-linecap="round" fill="none"/>`;
  let s="";
  items.forEach((it,i)=>{
    const cx=W/2+i*W,cy=70;
    it.rings.forEach(([r,n,k])=>{
      s+=`<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="currentColor" stroke-opacity=".55" stroke-width="1.3"/>`;
      const ang=[];
      if(n===8)[0,90,180,270].forEach(a=>{ang.push(a-9,a+9)});else for(let j=0;j<n;j++)ang.push(-90+j*360/n);
      ang.forEach((a,j)=>{const t=a*Math.PI/180,m=k.length===n?k[j]:k[0];s+=mk(m,cx+r*Math.cos(t),cy+r*Math.sin(t))});
    });
    s+=X1_T(cx,cy+5,it.s,{s:14,b:1});
    s+=`<path d="M${cx-58} 14H${cx-66}V126H${cx-58}M${cx+58} 14H${cx+66}V126H${cx+58}" fill="none" stroke="currentColor" stroke-width="1.6"/>`;
    s+=X1_T(cx+70,22,it.ch||".....",{a:"start",s:14,b:1});
  });
  return X1_FG(`0 0 ${W*items.length+30} 140`,s,cap,label,items.length*150);
}

/* particle pictures */
const X1_NA=(x0,y0,rows,cols,r1,r2,ids)=>{let s="";for(let i=0;i<rows;i++)for(let j=0;j<cols;j++){const pos=(i+j)%2===0,r=pos?r1:r2;s+=X1_C(x0+j*(r1+r2)+(pos?0:0),y0+i*(r1+r2),r,pos?ids[0]:ids[1],9)}return s};
function X1_PANEL(x,y,lab,inner){return `<g transform="translate(${x} ${y})">${inner}${X1_T(70,138,lab,{b:1,s:13})}</g>`}
function X1_Q1FIG(){
  const A=[[30,20],[85,12],[55,52],[18,70],[88,82],[40,105]].map(p=>X1_C(p[0]+20,p[1]+8,13,"He",9)).join("");
  /* diamond: simplified network */
  const dn=[[70,12],[50,30],[90,30],[40,55],[70,48],[100,55],[55,78],[85,78],[70,100],[30,80],[110,80],[70,125]],
        db=[[0,1],[0,2],[1,3],[1,4],[2,4],[2,5],[4,6],[4,7],[3,6],[5,7],[6,8],[7,8],[3,9],[5,10],[8,11]];
  const B=db.map(b=>X1_L(dn[b[0]][0],dn[b[0]][1],dn[b[1]][0],dn[b[1]][1],1.2)).join("")+dn.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="currentColor"/>`).join("");
  const Cc=X1_NA(18,22,4,4,12,10,["Cl⁻","Li⁺"]).replace(/Cl⁻/g,"Cl⁻").replace(/Li⁺/g,"Li⁺");
  /* in C the big ions are chloride: swap radii by drawing Cl bigger */
  let Cx="";for(let i=0;i<4;i++)for(let j=0;j<4;j++){const cl=(i+j)%2===0;Cx+=X1_C(28+j*26,24+i*26,cl?12:9,cl?"Cl⁻":"Li⁺",8)}
  const D=[[38,28,-12],[100,50,8],[40,92,80],[96,100,-50]].map(p=>`<g transform="translate(${p[0]} ${p[1]}) rotate(${p[2]})"><rect x="-26" y="-11" width="52" height="22" rx="11" fill="none" stroke="currentColor" stroke-opacity=".75" stroke-width="1.3"/>${X1_T(-14,4,"N",{s:11})}${X1_T(14,4,"N",{s:11})}${X1_L(-8,-2,8,-2,1)}${X1_L(-8,2,8,2,1)}${X1_L(-8,6,8,6,1)}</g>`).join("");
  let E="";for(let i=0;i<4;i++)for(let j=0;j<4;j++)E+=X1_C(22+j*24+(i%2?12:0),22+i*22,11.5,"Cu",8);
  return X1_FG("0 0 560 300",X1_PANEL(10,0,"A",A)+X1_PANEL(200,0,"B",B)+X1_PANEL(380,0,"C",Cx)+X1_PANEL(80,150,"D",D)+X1_PANEL(300,150,"E",E),"Part of the structures of five substances A to E (redrawn).","Particle diagrams of five substances A to E: separate helium atoms, a diamond network, a lattice of lithium and chloride ions, nitrogen molecules and a metal lattice of copper atoms",460);
}
function X1_Q3FIG(){
  const NaBr=X1_NA(30,22,4,4,17,13,["Br⁻","Na⁺"]);
  let Nb="";for(let i=0;i<4;i++)for(let j=0;j<4;j++){const br=(i+j)%2===0;Nb+=X1_C(34+j*34,26+i*34,br?16:12,br?"Br⁻":"Na⁺",9)}
  const ring=(cx,cy)=>{let p=[];for(let k=0;k<8;k++){const a=(k*45+22)*Math.PI/180;p.push([cx+22*Math.cos(a),cy+22*Math.sin(a)])}return `<path d="M${p.map(q=>q[0].toFixed(1)+" "+q[1].toFixed(1)).join("L")}Z" fill="none" stroke="currentColor" stroke-width="1.4"/>`+p.map(q=>`<circle cx="${q[0].toFixed(1)}" cy="${q[1].toFixed(1)}" r="3.2" fill="currentColor"/>`).join("")};
  const S=[[30,30],[90,30],[150,30],[30,90],[90,90],[150,90]].map(p=>ring(p[0]+10,p[1]+14)).join("");
  return X1_FG("0 0 440 190",`<g transform="translate(0 0)">${X1_T(85,14,"sodium bromide",{s:12})}<g transform="translate(15 10)">${Nb}</g></g><g transform="translate(220 0)">${X1_T(100,14,"sulfur",{s:12})}<g transform="translate(15 10)">${S}</g></g>`,"Part of the structures of sodium bromide and sulfur (redrawn: each sulfur ring is an S<sub>8</sub> molecule).","Lattice of sodium and bromide ions beside several eight-membered rings of sulfur atoms",420);
}
function X1_Q11FIG(){
  let R="";[[0,0],[1,0],[2,0],[3,0],[0.5,1],[1.5,1],[2.5,1],[0,2],[1,2],[2,2],[3,2]].forEach(p=>{R+=X1_C(30+p[0]*28,30+p[1]*24,13,"Zn",9)});
  const pp=[[60,10],[30,75],[100,60],[68,90]],bb=[[0,1],[0,2],[0,3],[1,2],[1,3],[2,3]];
  const S=bb.map(b=>X1_L(pp[b[0]][0],pp[b[0]][1],pp[b[1]][0],pp[b[1]][1],1.3)).join("")+pp.map(p=>X1_T(p[0],p[1]+5,"P",{s:12})).join("").replace(/<text/g,"<text");
  let T="";for(let i=0;i<3;i++)for(let j=0;j<3;j++){const br=(i+j)%2===0;T+=X1_C(26+j*36,26+i*36,br?17:13,br?"Br⁻":"Na⁺",9)}
  const hex=(cx,cy,dy)=>{let p=[];for(let k=0;k<6;k++){const a=(k*60)*Math.PI/180;p.push([cx+22*Math.cos(a),cy+dy+9*Math.sin(a)])}return p};
  const lay=(cx,cy)=>{const h=hex(cx,cy,0),h2=hex(cx+33,cy+0,0);return `<path d="M${h.map(q=>q[0].toFixed(1)+" "+q[1].toFixed(1)).join("L")}Z" fill="none" stroke="currentColor" stroke-width="1.2"/><path d="M${h2.map(q=>q[0].toFixed(1)+" "+q[1].toFixed(1)).join("L")}Z" fill="none" stroke="currentColor" stroke-width="1.2"/>`+h.concat(h2).map(q=>`<circle cx="${q[0].toFixed(1)}" cy="${q[1].toFixed(1)}" r="2.4" fill="currentColor"/>`).join("")};
  const U=lay(40,30)+lay(40,100)+[20,40,60,80].map((x,i)=>X1_L(18+i*22,34,18+i*22,96,1,1)).join("");
  return X1_FG("0 0 560 190",X1_PANEL(0,0,"R",R)+X1_PANEL(150,0,"S",S)+X1_PANEL(290,0,"T",T)+X1_PANEL(420,0,"U",U),"Part of the structures of four substances R, S, T and U (redrawn; U shows two layers).","Particle diagrams of four substances: a metal lattice of zinc atoms, a P4 molecule, a lattice of sodium and bromide ions, and layers of carbon atoms joined by dashed lines",460);
}
/* liquid / gas particle pictures */
function X1_ELL(){
  const e=[[40,30,20],[75,22,-30],[110,34,70],[145,26,10],[30,66,-60],[62,58,40],[96,66,-10],[130,62,80],[160,70,-40],[40,98,30],[78,98,-70],[112,100,15],[148,100,60],[26,126,-20],[64,132,50],[100,134,-50],[136,130,5],[164,128,-65]];
  return X1_FG("0 0 190 160",`<rect x="4" y="4" width="182" height="152" fill="none" stroke="currentColor" stroke-width="1.4"/>`+e.map(p=>`<ellipse cx="${p[0]}" cy="${p[1]}" rx="17" ry="7" transform="rotate(${p[2]} ${p[0]} ${p[1]})" fill="none" stroke="currentColor" stroke-opacity=".8" stroke-width="1.2"/>`).join(""),"Each oval is one molecule of carbon dioxide.","Many oval molecules packed closely together in random orientations",230);
}
function X1_TRI(){
  const t=[[40,28,20],[78,22,-40],[116,30,80],[26,64,-70],[62,60,30],[100,62,-20],[138,58,60],[42,98,50],[80,98,-80],[118,96,10],[152,92,-45],[60,130,20]];
  return X1_FG("0 0 190 160",t.map(p=>`<path transform="translate(${p[0]} ${p[1]}) rotate(${p[2]})" d="M-4 -15 Q4 -17 9 -6 Q13 6 8 13 Q0 17 -9 12 Q-13 3 -9 -8 Z" fill="none" stroke="currentColor" stroke-opacity=".8" stroke-width="1.2"/>`).join(""),"Each shape is one molecule of SO<sub>3</sub> at 30 °C.","Ten molecules of sulfur trioxide touching one another in an irregular arrangement",220);
}
function X1_AR(){
  return X1_FG("0 0 260 160",[[40,70],[80,30],[130,18],[180,50],[220,30],[110,70],[150,100],[60,120],[200,120]].map(p=>X1_C(p[0],p[1],14,"Ar",10)).join(""),"Substance R: argon atoms.","Nine argon atoms spread far apart",280);
}
function X1_CO(){
  return X1_FG("0 0 260 150",[[50,40,-10],[150,24,10],[70,100,70],[170,100,-60],[230,62,30]].map(p=>`<g transform="translate(${p[0]} ${p[1]}) rotate(${p[2]})"><rect x="-30" y="-12" width="60" height="24" rx="12" fill="none" stroke="currentColor" stroke-opacity=".8" stroke-width="1.3"/>${X1_T(-15,4,"C",{s:11})}${X1_T(15,4,"O",{s:11})}${X1_L(-8,-2,8,-2,1)}${X1_L(-8,2,8,2,1)}${X1_L(-8,6,8,6,1)}</g>`).join(""),"Substance Z: molecules of carbon monoxide, CO.","Five carbon monoxide molecules spread far apart in random orientations",280);
}
/* graphs */
function X1_GRID(x0,y0,w,h,xt,yt,xl,yl,xn,yn){
  let s=`<rect x="${x0}" y="${y0}" width="${w}" height="${h}" fill="none" stroke="currentColor" stroke-opacity=".25"/>`;
  for(let i=0;i<=xn;i++){const x=x0+w*i/xn;s+=`<path d="M${x} ${y0}V${y0+h}" stroke="currentColor" stroke-opacity=".12"/>`+X1_T(x,y0+h+14,xt[i],{s:10})}
  for(let j=0;j<=yn;j++){const y=y0+h-h*j/yn;s+=`<path d="M${x0} ${y}H${x0+w}" stroke="currentColor" stroke-opacity=".12"/>`+X1_T(x0-6,y+3.5,yt[j],{s:10,a:"end"})}
  return s+X1_T(x0+w/2,y0+h+32,xl,{s:11})+`<text x="14" y="${y0+h/2}" font-size="11" text-anchor="middle" transform="rotate(-90 14 ${y0+h/2})" fill="currentColor">${yl}</text>`;
}
function X1_Q3GRAPH(){
  return X1_FG("0 0 360 220",`<path d="M70 14V190H330" fill="none" stroke="currentColor" stroke-width="1.5"/>`+X1_T(46,100,"temperature",{s:11}).replace("<text",'<text transform="rotate(-90 46 100)"')+X1_T(200,212,"time",{s:12})+`<path d="M70 34L110 78H165L210 130H265L315 190" fill="none" stroke="currentColor" stroke-width="2"/>`+X1_T(108,70,"A",{b:1,s:13})+X1_T(167,70,"B",{b:1,s:13}),"Cooling curve of a gas.","Temperature falls, levels off between A and B, falls again, levels off again, then falls",340);
}
function X1_Q6GRAPH(){
  const xt=[],yt=[];for(let i=0;i<=12;i++)xt.push(i);for(let j=0;j<=12;j++)yt.push(j*20);
  const X=t=>46+t*(300/12),Y=T=>210-T*(190/240);
  return X1_FG("0 0 380 260",X1_GRID(46,20,300,190,xt,yt,"time / minutes","temperature / °C",12,12)+`<path d="M${X(0)} ${Y(20)}L${X(2)} ${Y(80)}L${X(5)} ${Y(80)}L${X(9)} ${Y(220)}" fill="none" stroke="currentColor" stroke-width="2"/>`,"Heating curve of pure solid Z (first 9 minutes).","Temperature rises from 20 to 80 degrees in 2 minutes, stays at 80 until 5 minutes, then rises to 220 degrees at 9 minutes",400);
}
function X1_Q9GRAPH(){
  const X=t=>50+t*(260/30),Y=T=>200-T*(180/300);
  const path=`M${X(0)} ${Y(300)}Q${X(1.5)} ${Y(235)} ${X(3.2)} ${Y(205)}H${X(12)}Q${X(15)} ${Y(172)} ${X(17)} ${Y(138)}H${X(23)}Q${X(27)} ${Y(118)} ${X(30)} ${Y(103)}`;
  let g=`<path d="M50 20V200H318" fill="none" stroke="currentColor" stroke-width="1.5"/>`;
  [0,50,100,150,200,250,300].forEach(v=>{g+=`<path d="M46 ${Y(v)}H50" stroke="currentColor"/>`+X1_T(42,Y(v)+3.5,v,{s:10,a:"end"})});
  [0,10,20,30].forEach(v=>{g+=`<path d="M${X(v)} 200V204" stroke="currentColor"/>`+X1_T(X(v),216,v,{s:10})});
  g+=`<path d="${path}" fill="none" stroke="currentColor" stroke-width="2"/>`;
  [["S",0,300,6,-4],["T",3,252,8,0],["V",6.5,205,0,-8],["W",12,205,4,-8],["X",15,170,8,-4],["Y",23,138,0,-8],["Z",30,103,4,-8]].forEach(l=>{g+=X1_T(X(l[1])+l[3],Y(l[2])+l[4],l[0],{b:1,s:13})});
  g+=X1_T(185,238,"time / minutes",{s:11})+`<text x="14" y="110" font-size="11" text-anchor="middle" transform="rotate(-90 14 110)" fill="currentColor">temperature / °C</text>`;
  return X1_FG("0 0 340 250",g,"Cooling curve of a substance that is a gas at the start.","Temperature falls from 300 degrees, levels off near 205 degrees, falls again, levels off near 140 degrees, then falls to about 105 degrees at 30 minutes",360);
}
/* sodium chloride cube (Q15 bonding) */
function X1_CUBE(ans){
  const v={BTL:[110,34],BTR:[220,34],BBL:[130,120],BBR:[220,120],FTL:[90,64],FTR:[190,64],FBL:[90,150],FBR:[190,150]};
  const sign={FTL:"+",FTR:"−",FBL:"−",FBR:"+",BTL:"−",BTR:"+",BBL:"+",BBR:"−"};
  const E=[["BTL","BTR"],["BTR","BBR"],["BBR","BBL"],["BBL","BTL"],["FTL","FTR"],["FTR","FBR"],["FBR","FBL"],["FBL","FTL"],["BTL","FTL"],["BTR","FTR"],["BBL","FBL"],["BBR","FBR"]];
  let s=E.map(e=>`<path d="M${v[e[0]][0]} ${v[e[0]][1]}L${v[e[1]][0]} ${v[e[1]][1]}" stroke="currentColor" stroke-opacity=".7" stroke-width="1.3"/>`).join("");
  for(const k in v){const show=ans||k==="FTL";s+=`<circle cx="${v[k][0]}" cy="${v[k][1]}" r="15" style="fill:var(--surface)" stroke="currentColor" stroke-width="1.4"/>`+(show?X1_T(v[k][0],v[k][1]+5,sign[k],{s:16,b:1}):"")}
  return X1_FG("0 0 310 180",s,ans?"Model answer.":"Part of the sodium chloride lattice. The ion at the front top left is Na⁺.","Cube with an ion at each corner; one corner is marked plus",300);
}

/* ===================== Topic 1: particulate nature of matter ===================== */
